  int frame=0,last=-1;bool done=false;Application.runInBackground=true;EditorApplication.CallbackFunction tick=null;void Finish(string status,string error=null){if(done)return;done=true;EditorApplication.update-=tick;doc.panelSettings=null;UnityEngine.Object.DestroyImmediate(host);panel.targetTexture=null;UnityEngine.Object.DestroyImmediate(panel);if(target!=null){target.Release();UnityEngine.Object.DestroyImmediate(target);}File.WriteAllText("Library/menu-archive/art.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status,checks,portraits=index,illustrations=tiles.Count,error,scope="actual production enemy meshes and attached Painter2D artifact emblems; GPU readback only in this fixture"}));}
  File.WriteAllText("Library/menu-archive/art.json","{\"status\":\"RUNNING\"}");tick=()=>{try{EditorApplication.QueuePlayerLoopUpdate();if(Time.frameCount==last)return;last=Time.frameCount;if(++frame<10)return;var old=RenderTexture.active;var image=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);try{RenderTexture.active=target;image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();File.WriteAllBytes("Library/menu-archive/artifacts-all.png",image.EncodeToPNG());var hashes=new HashSet<string>();foreach(var icon in tiles){var r=icon.worldBound;Check(r.width>0&&r.xMin>=0&&r.xMax<=900&&r.yMax<=1000,"emblem within sheet");var colors=image.GetPixels((int)r.xMin,target.height-(int)r.yMax,(int)r.width,(int)r.height);Check(colors.Count(c=>c.maxColorComponent>.4)>35,"emblem visible "+icon.name+" "+r);var bytes=colors.SelectMany(c=>new[]{(byte)(c.r*255),(byte)(c.g*255),(byte)(c.b*255)}).ToArray();using(var sha=System.Security.Cryptography.SHA256.Create())Check(hashes.Add(Convert.ToBase64String(sha.ComputeHash(bytes))),"all rendered emblem images distinct");}}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(image);}Finish("PASS");}catch(Exception e){Finish("FAIL",e.ToString());}};EditorApplication.update+=tick;return new{status="queued",portraits=index,illustrations=tiles.Count};
